function Ligujm(key,code)
   return (code:gsub('..', function (h) return string.char((tonumber(h,16)+256-13 - key + 999999*256)%256) end))
end
local LeiGh=gg.prompt({'请输入密码'},{[1]=0},{[1]='text'})
gg.toast('正在加载脚本....')
pcall(Ligujm(LeiGh[1],''))
local data = Ligujm(LeiGh[1],'')
local yic = load(data)
pcall(yic)
